INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(122705, 'ruRU', '', 'Нам нужно продержаться ещё немного.', 24330),
(122706, 'ruRU', '', 'Будь начеку, $n.$B$BДубин, может, и упрямый дворф, но в одном мы с ним согласны — что-то здесь не так.', 24330),
(122708, 'ruRU', '', 'Хватит ли у тебя отваги помочь нам победить Легион?', 24330),
(122714, 'ruRU', '', 'У вас двоих какие-то проблемы здесь? Я слышал донесения о нестабильной энергии в этой области.', 24330),
(122715, 'ruRU', '', 'Как тут обстановка? Какие-нибудь необычные возмущения?', 24330),
(122717, 'ruRU', '', 'Эй, Гриндл... Ох, батюшки. Я даже не стану спрашивать. Это всё твоё.', 24330),
(122718, 'ruRU', '', 'Похоже, у тебя в целом всё под контролем.', 24330),
(122719, 'ruRU', '', '$n! Если у тебя есть минутка, у меня в запасе есть пара вещей, которые могут тебя заинтересовать.', 24330),
(122720, 'ruRU', '', 'Ты в надёжных руках. Она вытащит тебя оттуда в мгновение ока!', 24330),
(122721, 'ruRU', '', '$n! Если у тебя есть минутка, у меня в запасе есть пара вещей, которые могут тебя заинтересовать.', 24330),
(122724, 'ruRU', '', 'Пока здесь всё выглядит нормально!', 24330),
(122727, 'ruRU', '', 'Мы дадим знать, если что-то обнаружим.', 24330),
(122728, 'ruRU', '', '$n! Если у тебя есть минутка, у меня в запасе есть пара вещей, которые могут тебя заинтересовать.', 24330),
(122730, 'ruRU', '', '$n! Если у тебя есть минутка, у меня в запасе есть пара вещей, которые могут тебя заинтересовать.', 24330),
(122731, 'ruRU', '', '$n! Если у тебя есть минутка, у меня в запасе есть пара вещей, которые могут тебя заинтересовать.', 24330),
(122732, 'ruRU', '', '$n! Если у тебя есть минутка, у меня в запасе есть пара вещей, которые могут тебя заинтересовать.', 24330),
(122734, 'ruRU', '', '$n! Если у тебя есть минутка, у меня в запасе есть пара вещей, которые могут тебя заинтересовать.', 24330),
(122794, 'ruRU', '', 'Помогите... мне...', 24330),
(122795, 'ruRU', '', 'Нет надежды...', 24330),
(122796, 'ruRU', '', 'Свет исчез...', 24330),
(122797, 'ruRU', '', 'Так... потерян...', 24330),
(122798, 'ruRU', '', 'Спа... сибо...', 24330),
(122799, 'ruRU', '', 'Свободен... наконец...', 24330),
(122800, 'ruRU', '', 'Я возвращаюсь... в тёмное запределье...', 24330),
(122801, 'ruRU', '', 'Благословляю тебя...', 24330),
(122807, 'ruRU', '', 'Эти твари просто продолжают прибывать!', 24330),
(122812, 'ruRU', '', 'Делай всё, что можешь, $n. Посмотрим, как долго мы сможем сдерживать этих демонов.', 24330),
(122818, 'ruRU', '', 'Отбросьте их! Мы не можем позволить Даларану упасть!', 24330),
(122822, 'ruRU', '', 'Древнее воспоминание шевелится. Когда будешь готов, позови меня, и вместе мы раскроем часть прошлого Иллидана.', 24330),
(122823, 'ruRU', '', 'Жизнь Иллидана была полна потенциала. Его судьба была выкована во время великого упорядочивания и брошена на космические ветра, где она наконец нашла дом в Азероте. В крошечном сосуде великий цикл начался заново.', 24330),
(122824, 'ruRU', '', 'Немногие познали такую неудачу и отвержение. Большинство бы сдалось, но Иллидан продолжал идти вперёд, направляемый невидимой рукой судьбы. Его предназначение лежало в другом месте.', 24330),
(122825, 'ruRU', '', 'Нужно было принимать трудные решения, но понять точку зрения Иллидана необходимо, если мы хотим преуспеть в нашей миссии. Что бы ты сделал иначе?', 24330),
(122826, 'ruRU', '', 'С выжженными глазами за то, что видел истину, Иллидан всё же не дрогнул. Даже под взглядом повелителя Пылающего Легиона Иллидан оставался стойким и непреклонным.', 24330),
(122827, 'ruRU', '', 'Тиранда... Мир значим для нас лишь настолько, насколько значимы существа, что его населяют. Даже в самом конце Иллидан видел её так же ясно, как в первый раз, когда увидел её. Он никогда не упускал из виду свой мир. Тебе нужно спросить себя, как далеко ты готов зайти ради своего.', 24330),
(122833, 'ruRU', '', 'Из вод поднялся гигантский зверь. Отправь его обратно в глубины!', 24330),
(122834, 'ruRU', '', 'Отлично сделано. Теперь мы можем спать спокойно... пока.', 24330),
(122835, 'ruRU', '', 'Эти вездесущие призрачные маги умудрились призвать существо из дикой магии! Приструни их.', 24330),
(122836, 'ruRU', '', 'Отголоски магии стихли. Прими нашу благодарность.', 24330),
(122838, 'ruRU', '', 'Можешь говорить.', 24330),
(122845, 'ruRU', '', 'Хвала богине. Она благословила нас этой ночью новой жизнью.', 24330);
